mapper.select:
SELECT id, monitor_id, snapshot_date, category, rank_main, sub_category, rank_sub, rating, review_count, seller_count, price,
       title, main_image, listing_status, source, create_time, update_time
FROM ecom_monitor_snapshot
WHERE monitor_id = #{monitorId}
AND snapshot_date >= #{begin}
AND snapshot_date <= #{end}
ORDER BY snapshot_date
